// earcut.rs — Rust port of mapbox earcut polygon triangulation

type N = u32;

#[derive(Clone)]
struct Node {
    i: N,
    x: f64,
    y: f64,
    prev: usize,
    next: usize,
    z: i32,
    prev_z: Option<usize>,
    next_z: Option<usize>,
    steiner: bool,
}

pub struct Earcut {
    nodes: Vec<Node>,
    pub indices: Vec<N>,
    vertices: usize,
    hashing: bool,
    min_x: f64,
    max_x: f64,
    min_y: f64,
    max_y: f64,
    inv_size: f64,
}

impl Earcut {
    pub fn new() -> Self { ... }

    pub fn run(&mut self, points: &[Vec<[f64; 2]>]) {
        self.indices.clear();
        self.vertices = 0;
        if points.is_empty() { return; }

        let mut threshold: i64 = 80;
        let mut i = 0;
        while threshold >= 0 && i < points.len() {
            threshold -= points[i].len() as i64;
            i += 1;
        }

        let outer_node = match self.linked_list(&points[0], true) {
            Some(n) => n,
            None => return,
        };
        if self.nodes[outer_node].prev == self.nodes[outer_node].next { return; }

        let mut outer_node = outer_node;
        if points.len() > 1 {
            outer_node = self.eliminate_holes(points, outer_node);
        }

        self.hashing = threshold < 0;
        if self.hashing {
            let mut p = self.nodes[outer_node].next;
            self.min_x = self.nodes[outer_node].x;
            self.max_x = self.nodes[outer_node].x;
            self.min_y = self.nodes[outer_node].y;
            self.max_y = self.nodes[outer_node].y;
            loop {
                let x = self.nodes[p].x;
                let y = self.nodes[p].y;
                if x < self.min_x { self.min_x = x; }
