fn linked_list(&mut self, points: &[[f64; 2]], clockwise: bool) -> Option<usize> {
    let mut sum = 0.0f64;
    let len = points.len();
    let mut last: Option<usize> = None;
    let mut i = 0;
    let mut j = if len > 0 { len - 1 } else { 0 };
    while i < len {
        let p1 = points[i];
        let p2 = points[j];
        sum += (p2[0] - p1[0]) * (p1[1] + p2[1]);
        j = i;
        i += 1;
    }

    if clockwise == (sum > 0.0) {
        for i in 0..len {
            last = Some(self.insert_node(self.vertices + i, points[i], last));
        }
    } else {
        let mut i = len;
        while i > 0 {
            i -= 1;
            last = Some(self.insert_node(self.vertices + i, points[i], last));
        }
    }

    if let Some(l) = last {
        let next = self.nodes[l].next;
        if self.equals(l, next) {
            self.remove_node(l);
            last = Some(next);
        }
    }

    self.vertices += len;
    last
}
