        let pn = self.nodes[p].next;
        let pny = self.nodes[pn].y;
        if hy <= py && hy >= pny && pny != py {
            let px = self.nodes[p].x;
            let pnx = self.nodes[pn].x;
            let x = px + (hy - py) * (pnx - px) / (pny - py);
            if x <= hx && x > qx {
                qx = x;
                if x == hx {
                    if hy == py { return Some(p); }
                    if hy == pny { return Some(pn); }
